package br.com.sistemacardapio.pedido;
import java.math.BigDecimal;import java.time.Instant;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ClientePublicService{private final JdbcTemplate jdbc;private final PasswordEncoder encoder;public ClientePublicService(JdbcTemplate jdbc,PasswordEncoder encoder){this.jdbc=jdbc;this.encoder=encoder;}@Transactional public void cadastrar(Cadastro request){if(request.nome()==null||request.nome().isBlank())throw new IllegalStateException("Nome é obrigatório");if(request.senha()==null||request.senha().length()<6)throw new IllegalStateException("A senha deve possuir pelo menos 6 caracteres");String telefone=telefone(request.telefone());if(telefone.length()<10)throw new IllegalStateException("Telefone inválido");Cliente atual=jdbc.query("select id,senha_hash from cliente where telefone_normalizado=?",rs->rs.next()?new Cliente(rs.getObject(1,UUID.class),rs.getString(2)):null,telefone);if(atual!=null&&atual.hash()!=null)throw new IllegalStateException("Este telefone já possui cadastro");String hash=encoder.encode(request.senha());if(atual==null)jdbc.update("insert into cliente(id,telefone_normalizado,nome,email,senha_hash) values(?,?,?,?,?)",UUID.randomUUID(),telefone,request.nome().trim(),limpar(request.email()),hash);else jdbc.update("update cliente set nome=?,email=?,senha_hash=?,atualizado_em=now() where id=?",request.nome().trim(),limpar(request.email()),hash,atual.id());}@Transactional(readOnly=true)public List<PedidoCliente>historico(Login request){String telefone=telefone(request.telefone());Cliente cliente=jdbc.query("select id,senha_hash from cliente where telefone_normalizado=?",rs->rs.next()?new Cliente(rs.getObject(1,UUID.class),rs.getString(2)):null,telefone);if(cliente==null||cliente.hash()==null||!encoder.matches(request.senha(),cliente.hash()))throw new IllegalStateException("Telefone ou senha inválidos");return jdbc.query("select p.id,p.numero,e.nome_fantasia,e.slug,e.logo_arquivo_id,p.modalidade,p.status,p.total,p.criado_em,p.agendado_para,(select coalesce(sum(i.quantidade),0) from pedido_item i where i.pedido_id=p.id) from pedido p join empresa e on e.id=p.empresa_id where p.cliente_id=? order by p.criado_em desc",(rs,n)->new PedidoCliente(rs.getObject(1,UUID.class),rs.getLong(2),rs.getString(3),rs.getString(4),rs.getObject(5,UUID.class),rs.getString(6),rs.getString(7),rs.getBigDecimal(8),rs.getObject(9,Instant.class),rs.getObject(10,Instant.class),rs.getInt(11)),cliente.id());}private String telefone(String value){return value==null?"":value.replaceAll("\\D","");}private String limpar(String value){return value==null||value.isBlank()?null:value.trim();}public record Cadastro(String nome,String telefone,String email,String senha){}public record Login(String telefone,String senha){}private record Cliente(UUID id,String hash){}public record PedidoCliente(UUID id,long numero,String empresa,String empresaSlug,UUID logoArquivoId,String modalidade,String status,BigDecimal total,Instant criadoEm,Instant agendadoPara,int quantidadeItens){}
}
